PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE polyclinics (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL
    , login TEXT, password TEXT, root INTEGER, razdel TEXT);
CREATE TABLE specialties (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        load_clinic_per_hour REAL, 
        load_home_per_hour REAL,    
        time_clinic INTEGER,       
        time_home INTEGER,         
        coefficient REAL DEFAULT 0.923
    );
CREATE TABLE doctors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    full_name TEXT NOT NULL,
    login TEXT UNIQUE,
    password TEXT,
    is_admin INTEGER DEFAULT 0
    );
CREATE TABLE rates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        polyclinic_id INTEGER REFERENCES polyclinics(id),
        specialty_id INTEGER REFERENCES specialties(id),
        doctor_id INTEGER REFERENCES doctors(id),
        rate_count REAL NOT NULL,  
        salary_bonus REAL          
    , workload_clinic INTEGER, workload_home INTEGER, time_clinic INTEGER, time_home INTEGER);
CREATE TABLE doctor_work (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        polyclinic_id INTEGER REFERENCES polyclinics(id),
        specialty_id INTEGER REFERENCES specialties(id),
        doctor_id INTEGER REFERENCES doctors(id),
        month DATE NOT NULL,       
        planned_visits INTEGER,   
        actual_visits INTEGER      
    , rate_count REAL, salary_bonus REAL, planned_work_days INTEGER, actual_work_days INTEGER, time_clinic INTEGER, time_home INTEGER, actual_visit_dom INTEGER);
CREATE TABLE IF NOT EXISTS "otchet" (
	"ID"	INTEGER,
	"name"	TEXT,
	"sql"	TEXT,
	"json"	TEXT,
	"js"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "razdel" (
	"id"	INTEGER,
	"path"	TEXT,
	"name"	TEXT, icon TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE polyclinic_stats (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Дата создания записи
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  -- Дата изменения записи
    record_date DATE NOT NULL,                      -- Дата учета статистики
    polyclinic_id INTEGER NOT NULL,                 -- ID поликлиники
    planned_beds INTEGER,                           -- Койки (плановые показатели)
    admitted_daily INTEGER,                         -- Количество поступивших за сутки
    discharged_daily INTEGER,                       -- Количество выписанных за сутки
    patients_at_8am INTEGER,                        -- Лежит больных на 8.00
    died_daily INTEGER,                             -- Умерло больных за сутки
    
    FOREIGN KEY (polyclinic_id) REFERENCES polyclinics(id),
    UNIQUE (record_date, polyclinic_id)             -- Одна запись на поликлинику в день
);
CREATE TABLE nozologii (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,         -- название заболевания
    parent_id INTEGER,          -- ссылка на родителя (NULL или id другой нозологии)
    FOREIGN KEY (parent_id) REFERENCES nozologii(id)
);
CREATE TABLE nozologiya_stats (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    polyclinic_id INTEGER NOT NULL,       -- поликлиника, под которой зашли
    nozologiya_id INTEGER NOT NULL,        -- заболевание из справочника нозологий
    month_year TEXT NOT NULL,              -- месяц-год в формате YYYY-MM
    total_cases INTEGER NOT NULL DEFAULT 0, -- всего заболевших
    first_cases INTEGER NOT NULL DEFAULT 0, -- впервые заболевших
    age_type INTEGER NOT NULL,             -- 1, 2 или 3
    FOREIGN KEY (polyclinic_id) REFERENCES polyclinics(id),
    FOREIGN KEY (nozologiya_id) REFERENCES nozologii(id)
);
CREATE TABLE attached_children (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            polyclinic_id INTEGER NOT NULL,
            count_18_plus INTEGER NOT NULL DEFAULT 0,
            count_15_17  INTEGER NOT NULL DEFAULT 0,
            count_0_14   INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (polyclinic_id) REFERENCES polyclinics(id)
        );
CREATE TABLE forms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    polyclinic_id INTEGER NOT NULL,      -- форма принадлежит поликлинике
    title TEXT NOT NULL,
    description TEXT,
    slug TEXT UNIQUE NOT NULL,

    -- настройки доступа
    access_start DATE,
    access_end DATE,
    allow_edit BOOLEAN DEFAULT 0,
    edit_until DATE,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, is_active INTEGER DEFAULT 1, allowed_days_of_month TEXT, allowed_days_of_week TEXT, allowed_days_of_year TEXT,

    FOREIGN KEY (polyclinic_id) REFERENCES polyclinics(id) ON DELETE CASCADE
);
CREATE TABLE form_fields (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    form_id INTEGER NOT NULL,
    type TEXT NOT NULL,                  -- text, number, date, checkbox, select и т.п.
    label TEXT NOT NULL,                 -- заголовок вопроса
    name TEXT NOT NULL,                  -- машинное имя (ключ)
    required BOOLEAN DEFAULT 0,
    options_json TEXT,                   -- список вариантов (для select/checkbox/radio) в JSON
    order_index INTEGER DEFAULT 0, directory_id INTEGER REFERENCES directories(id), constraints_json TEXT, formula TEXT,

    FOREIGN KEY (form_id) REFERENCES forms(id) ON DELETE CASCADE
);
CREATE TABLE form_responses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    form_id INTEGER NOT NULL,
    polyclinic_id INTEGER NOT NULL,
    submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP,
    status TEXT DEFAULT 'ok', created_at TEXT DEFAULT CURRENT_TIMESTAMP,            -- ok / archived / spam

    FOREIGN KEY (form_id) REFERENCES forms(id) ON DELETE CASCADE,
    FOREIGN KEY (polyclinic_id) REFERENCES polyclinics(id) ON DELETE CASCADE
);
CREATE TABLE form_response_values (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    response_id INTEGER NOT NULL,
    field_id INTEGER NOT NULL,
    value_text TEXT,                     -- универсальное текстовое
    value_number REAL,                   -- числовое
    value_date DATE,                     -- даты
    value_json TEXT,                     -- JSON: списки, чекбоксы, файлы

    FOREIGN KEY (response_id) REFERENCES form_responses(id) ON DELETE CASCADE,
    FOREIGN KEY (field_id) REFERENCES form_fields(id) ON DELETE CASCADE
);
CREATE TABLE directories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,   -- название справочника
    description TEXT             -- пояснение
);
CREATE TABLE directory_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    directory_id INTEGER NOT NULL,
    value TEXT NOT NULL,
    FOREIGN KEY (directory_id) REFERENCES directories(id) ON DELETE CASCADE
);
CREATE TABLE dashboard_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    sql TEXT NOT NULL,
    json TEXT,         -- описание параметров (фильтры, подписи)
    js TEXT,           -- код визуализации (если нужно кастомизировать)
    position INTEGER,  -- порядок на экране дашборда
    chart_type TEXT,   -- тип графика (line, bar, pie, table и т.п.)
    is_active INTEGER DEFAULT 1
, col_size INTEGER DEFAULT 6);
CREATE TABLE dashboard_shares (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    password TEXT NOT NULL UNIQUE,
    allowed_reports TEXT NOT NULL, -- список id графиков через запятую
    valid_until TEXT NOT NULL      -- дата в формате YYYY-MM-DD HH:MM
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_nozologii_parent ON nozologii(parent_id);
CREATE UNIQUE INDEX ux_attached_children_polyclinic
ON attached_children (polyclinic_id);
CREATE INDEX idx_forms_slug ON forms(slug);
COMMIT;
