INSERT INTO otchet VALUES(1,'Пароли к поликлиникам','SELECT polyclinics.name,polyclinics.login,polyclinics.password,polyclinics.razdel FROM polyclinics','','');
INSERT INTO otchet VALUES(2,'Отчет по поликлиникам',replace(replace('SELECT dw.id, p.name as polyclinic, s.name as specialty, d.full_name as doctor,\r\n               dw.month, dw.planned_visits, dw.actual_visits, dw.rate_count, dw.salary_bonus,\r\n               dw.planned_work_days, dw.actual_work_days, dw.time_clinic, dw.time_home, dw.actual_visit_dom,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE ((dw.actual_visit_dom + dw.actual_visits) * 100.0 / dw.planned_visits)\r\n               END as proc,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE ((dw.actual_visits) * 100.0 / dw.planned_visits)\r\n               END as proc_act,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE (((dw.actual_visit_dom + dw.actual_visits) * 100.0 / dw.planned_visits) - ((dw.actual_visits) * 100.0 / dw.planned_visits))\r\n               END as proc_ndom\r\n        FROM doctor_work dw\r\n        JOIN polyclinics p ON dw.polyclinic_id = p.id\r\n        JOIN specialties s ON dw.specialty_id = s.id\r\n        JOIN doctors d ON dw.doctor_id = d.id\r\n       where dw.polyclinic_id=:Poliklinika\r\n        ORDER BY dw.month DESC','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"Поликлиника","aname":"Poliklinika","sel":"5","spisok":"SELECT id,name FROM polyclinics "}]','');
INSERT INTO otchet VALUES(3,'Отчет по койкам по направлениям',replace(replace('WITH RECURSIVE hierarchy AS (\r\n    SELECT \r\n        id, \r\n        name, \r\n        root, \r\n        0 AS level,\r\n        CAST(id AS TEXT) AS path\r\n    FROM polyclinics\r\n    WHERE  id=:TsRB\r\n    \r\n    UNION ALL\r\n    \r\n    SELECT \r\n        p.id, \r\n        p.name, \r\n        p.root, \r\n        h.level + 1,\r\n        h.path || '','' || CAST(p.id AS TEXT) AS path\r\n    FROM polyclinics p\r\n    JOIN hierarchy h ON p.root = h.id\r\n),\r\nstats_with_hierarchy AS (\r\n    SELECT \r\n        h.id,\r\n        h.name,\r\n        h.root,\r\n        h.level,\r\n        h.path,\r\n        ps.record_date,\r\n        ps.planned_beds,\r\n        ps.admitted_daily,\r\n        ps.discharged_daily,\r\n        ps.patients_at_8am,\r\n        ps.died_daily\r\n    FROM hierarchy h\r\n    LEFT JOIN polyclinic_stats ps ON h.id = ps.polyclinic_id\r\n   -- WHERE ps.record_date = ?  -- Здесь можно указать конкретную дату или убрать условие для всех дат\r\n),\r\naggregated_stats AS (\r\n    SELECT \r\n        h.id,\r\n        h.name,\r\n        h.root,\r\n        h.level,\r\n        h.path,\r\n        SUM(s.planned_beds) AS total_planned_beds,\r\n        SUM(s.admitted_daily) AS total_admitted_daily,\r\n        SUM(s.discharged_daily) AS total_discharged_daily,\r\n        SUM(s.patients_at_8am) AS total_patients_at_8am,\r\n        SUM(s.died_daily) AS total_died_daily\r\n    FROM hierarchy h\r\n    LEFT JOIN stats_with_hierarchy s ON s.path LIKE h.path || ''%''  -- Все дочерние поликлиники\r\n    GROUP BY h.id, h.name, h.root, h.level, h.path\r\n)\r\nSELECT \r\n    id, \r\n    name, \r\n    root, \r\n    level,\r\n    path,\r\n    total_planned_beds,\r\n    total_admitted_daily,\r\n    total_discharged_daily,\r\n    total_patients_at_8am,\r\n    total_died_daily\r\nFROM aggregated_stats\r\nORDER BY path;','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"ЦРБ","aname":"TsRB","sel":"5","spisok":"SELECT id,name FROM polyclinics WHERE root is NULL or root<0"}]','');
INSERT INTO otchet VALUES(4,'отчет по всем поликлиникам по месяцам',replace(replace('SELECT dw.id, p.name as polyclinic, s.name as specialty, d.full_name as doctor,\r\n               dw.month, dw.planned_visits, dw.actual_visits, dw.rate_count, dw.salary_bonus,\r\n               dw.planned_work_days, dw.actual_work_days, dw.time_clinic, dw.time_home, dw.actual_visit_dom,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE ((dw.actual_visit_dom + dw.actual_visits) * 100.0 / dw.planned_visits)\r\n               END as proc,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE ((dw.actual_visits) * 100.0 / dw.planned_visits)\r\n               END as proc_act,\r\n               CASE \r\n                 WHEN dw.planned_visits = 0 THEN 0 \r\n                 ELSE (((dw.actual_visit_dom + dw.actual_visits) * 100.0 / dw.planned_visits) - ((dw.actual_visits) * 100.0 / dw.planned_visits))\r\n               END as proc_ndom\r\n        FROM doctor_work dw\r\n        JOIN polyclinics p ON dw.polyclinic_id = p.id\r\n        JOIN specialties s ON dw.specialty_id = s.id\r\n        JOIN doctors d ON dw.doctor_id = d.id\r\n       where dw.month>=:nachalo and dw.month<=:okonchanie\r\n        ORDER BY dw.month,p.name DESC','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"начало","aname":"nachalo","sel":"4","spisok":""},{"ogr":"","name":"окончание","aname":"okonchanie","sel":"4","spisok":""}]','');
INSERT INTO otchet VALUES(5,'отчет по формам',replace(replace('SELECT\r\n    r.id AS response_id,\r\n    r.submitted_at,\r\n    p.name AS polyclinic_name,\r\n    json_group_object(f.label, COALESCE(v.value_text, v.value_number, v.value_date, v.value_json)) AS answers\r\nFROM form_responses r\r\nJOIN form_response_values v ON v.response_id = r.id\r\nJOIN form_fields f ON f.id = v.field_id\r\nLEFT JOIN polyclinics p ON p.id = r.polyclinic_id\r\nWHERE r.form_id = :forma\r\n  AND date(r.submitted_at) BETWEEN date(:Nachalo) AND date(:Okonchanie)\r\nGROUP BY r.id, r.submitted_at, p.name\r\nORDER BY r.submitted_at, r.id;\r\n','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"форма","aname":"forma","sel":"5","spisok":"SELECT id, title as name FROM forms ORDER BY id;"},{"ogr":"","name":"Начало","aname":"Nachalo","sel":"3","spisok":""},{"ogr":"","name":"Окончание","aname":"Okonchanie","sel":"3","spisok":""}]','');
INSERT INTO otchet VALUES(6,'Отчет по исследованиям',replace(replace('SELECT\r\n    r.id AS response_id,\r\n    r.submitted_at,\r\n    p.name AS polyclinic_name,\r\n    json_group_object(\r\n        f.label,\r\n        COALESCE(v.value_text, v.value_number, v.value_date, v.value_json)\r\n    ) AS answers\r\nFROM form_responses r\r\nJOIN form_response_values v ON v.response_id = r.id\r\nJOIN form_fields f ON f.id = v.field_id\r\nLEFT JOIN polyclinics p ON p.id = r.polyclinic_id\r\nWHERE r.form_id = 1\r\n  AND EXISTS (\r\n        SELECT 1\r\n        FROM form_response_values v2\r\n        JOIN form_fields f2 ON f2.id = v2.field_id\r\n        WHERE v2.response_id = r.id\r\n          AND f2.name = ''field_1''\r\n          AND date(v2.value_text || ''-15'') >= date(:Nachalo || ''-01'')\r\n          AND date(v2.value_text || ''-15'') <= date(:Okonchanie || ''-01'', ''+1 month'', ''-1 day'')\r\n    )\r\nGROUP BY r.id, r.submitted_at, p.name\r\nORDER BY r.submitted_at, r.id;\r\n','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"Начало","aname":"Nachalo","sel":"7","spisok":""},{"ogr":"","name":"Окончание","aname":"Okonchanie","sel":"7","spisok":""}]','');
