INSERT INTO dashboard_reports VALUES(1,'Отчет по исследованиям',replace(replace('SELECT  \r\n     \r\n (\r\n        SELECT COALESCE(vm.value_text, vm.value_number, vm.value_date, vm.value_json)\r\n        FROM form_response_values vm\r\n        JOIN form_fields fm ON vm.field_id = fm.id\r\n        WHERE vm.response_id = r.id AND fm.label = ''Месяц''\r\n        LIMIT 1\r\n    ) AS month,\r\n    (COALESCE(v.value_text, v.value_number, v.value_date, v.value_json)) AS "Количество"\r\n\r\nFROM form_responses r\r\nJOIN form_response_values v ON r.id = v.response_id \r\nJOIN form_fields f ON v.field_id = f.id\r\nWHERE r.form_id = 1\r\n  AND r.polyclinic_id = :Poli\r\n  AND f.label <> ''Месяц''\r\n  AND f.label = :Tp\r\nORDER BY f.label;','\r',char(13)),'\n',char(10)),'[{"ogr":"","name":"Начало","aname":"Nachalo","sel":"7","spisok":"MONTH-6"},{"ogr":"","name":"Окончание","aname":"Okon","sel":"7","spisok":"MONTH+6"},{"ogr":"","name":"поликлиника","aname":"Poli","sel":"5","spisok":"SELECT id,name from polyclinics "},{"ogr":"","name":"Тип исследования","aname":"Tp","sel":"5","spisok":"SELECT f.label AS  \"id\",  f.label AS  \"name\" FROM form_responses r JOIN form_response_values v ON r.id = v.response_id  JOIN form_fields f ON v.field_id = f.id JOIN polyclinics p ON r.polyclinic_id = p.id WHERE r.form_id =1  GROUP BY   f.label ORDER BY   f.label;"}]','',0,'bar',1,6);
